def check(candidate):
    assert candidate("(({{[[]]}}))") == [("(({{[[]]}}))", {"()": 2, "{}": 2, "[]": 2})]
    try:
        candidate("([)]")
        assert False, "Expected ValueError for mismatched parentheses"
    except ValueError as e:
        assert str(e) == "Mismatched parentheses: ([)]"

